"""Bracket balancing with double-quoted string handling."""


def balanced(s):
    """Return True if every (), [], and {} in *s* is correctly matched.

    Brackets inside double-quoted strings are ignored.  Within a string a
    backslash escapes the following character, so \" does not terminate it.
    An unterminated string makes the input unbalanced.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_string = False
    i = 0

    while i < len(s):
        ch = s[i]

        if in_string:
            if ch == '\\':
                # Skip this backslash and the character it escapes.
                if i + 1 >= len(s):
                    return False  # dangling escape: unterminated string
                i += 2
                continue
            if ch == '"':
                in_string = False
            i += 1
            continue

        if ch == '"':
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False

        i += 1

    return not in_string and not stack
